    "kernel_code": "1: \"\"\"Elementwise base-two exponential with integer range reduction.\"\"\"\n2: import torch\n3: import triton\n4: import triton.language as tl\n5: \n6: \n7: @triton.jit\n8: def _exp2_kernel(X, OUT, N: tl.constexpr, BLOCK: tl.constexpr):\n9:     index = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)\n10:     active = index < N\n11:     x = tl.load(X + index, mask=active, other=0.0).to(tl.float32)\n12:     integer = tl.floor(x + 0.5).to(tl.int32)\n13:     fraction = x - integer.to(tl.float32)\n14:     polynomial = 0.00133909\n15:     polynomial = polynomial * fraction + 0.00967603\n16:     polynomial = polynomial * fraction + 0.0555036\n17:     polynomial = polynomial * fraction + 0.240221\n18:     polynomial = polynomial * fraction + 0.693147\n19:     polynomial = polynomial * fraction + 1.0\n20:     scale = ((integer + 127) << 23).to(tl.float32, bitcast=True)\n21:     value = scale * polynomial\n22:     tl.store(OUT + index, value, mask=active)\n23: \n24: \n25: def validate_inputs(x, require_cuda=True):\n26:     \"\"\"Validate the complete public input domain; also usable on CPU.\"\"\"\n27:     def require(condition, message):\n28:         if not condition:\n29:             raise ValueError(message)\n30: \n31:     require(not torch.is_inference_mode_enabled(), \"ordinary execution mode required\")\n32:     require(type(x) is torch.Tensor, \"ordinary torch.Tensor required\")\n33:     require(x.layout == torch.strided and x.is_contiguous(),\n34:             \"contiguous strided input required\")\n35:     require(not x.requires_grad and not x.is_inference(),\n36:             \"ordinary non-gradient input required\")\n37:     require(not x.is_neg() and not x.is_conj(),\n38:             \"logical view flags are outside this domain\")\n39:     require(not require_cuda or x.is_cuda, \"CUDA input required by run\")\n40:     require(x.ndim == 1 and 1 <= x.numel() <= 131072,\n41:             \"x must have shape [N] with N in [1,131072]\")\n42:     require(x.dtype == torch.bfloat16, \"BF16 input required\")\n43:     require(bool(torch.isfinite(x).all().item()), \"all input values must be finite\")\n44:     require(bool((x.abs() <= 10).all().item()), \"all input values must be in [-10,10]\")\n45:     return {\"valid\": True, \"size\": x.numel()}\n46: \n47: \n48: def run(x):\n49:     \"\"\"Return a fresh FP32 tensor approximating 2**x for every stored input.\"\"\"\n50:     validate_inputs(x)\n51:     n = x.numel()\n52:     with torch.cuda.device(x.device):\n53:         output = torch.empty((n,), dtype=torch.float32, device=x.device)\n54:         _exp2_kernel[(triton.cdiv(n, 256),)](\n55:             x, output, N=n, BLOCK=256, num_warps=4, enable_fp_fusion=False)\n56:     return output\n57: \n58: \n59: def reference(x):\n60:     \"\"\"Evaluate mathematical exp2 independently using the FP64 library function.\"\"\"\n61:     validate_inputs(x, require_cuda=False)\n62:     return torch.exp2(x.to(torch.float64))\n63: \n64: \n65: def make_inputs(device=\"cuda\", size=4093, seed=0):\n66:     \"\"\"Convenience example generator, not a restriction on the input domain.\"\"\"\n67:     generator = torch.Generator(device=\"cpu\").manual_seed(seed)\n68:     x = (20.0 * torch.rand((size,), generator=generator) - 10.0).to(torch.bfloat16)\n69:     return (x.to(device),)",
